pub fn simple_nested(a: &mut Vec<i32>, b: &Vec<i32>, N: i32) -> i32 {
    let mut sum = 0;
    
    for i in 0..N as usize {
        if b[i] == i as i32 {
            a[i] = 1;
            sum += 1;
        } else if b[i] == i as i32 + 1 {
            a[i] = 2;
            sum += 2;
        }
        // According to the problem statement, b[i] must be either i or i+1,
        // so we don't need an else case
    }
    
    sum
}